\set ON_ERROR_STOP on
do $$begin
 if current_database()<>'byus_clean'or inet_server_addr()is not null then raise exception 'Disposable Unixsocket byus_clean required';end if;
 if exists(select 1 from public.activity_evidence_upgrade_expected e join public.group_mission_submissions s on e.kind='mission'and e.id=s.id where(to_jsonb(s)-array['current_revision','evidence_id','original_attested','submission_kind','survey_response'])<>e.original or s.current_revision<>1 or s.evidence_id is not null or s.original_attested or s.submission_kind<>'text'or s.survey_response is not null)then raise exception 'Existing submission changed during backfill';end if;
 if(select count(*)from public.group_mission_submission_revisions where submission_id::text like'e9760000-%')<>3 or exists(select 1 from public.group_mission_submission_revisions v join public.activity_evidence_upgrade_expected e on e.kind='mission'and e.id=v.submission_id where v.revision<>1 or v.body<>e.original->>'body'or v.created_at<>(e.original->>'created_at')::timestamptz or v.evidence_id is not null)then raise exception 'Existing submission revision backfill differs';end if;
 if(select count(*)from public.group_mission_submission_reviews where submission_id::text like'e9760000-%')<>2 or exists(select 1 from public.group_mission_submission_reviews v join public.activity_evidence_upgrade_expected e on e.kind='mission'and e.id=v.submission_id where v.revision<>1 or v.action<>(case when e.original->>'status'='completed'then'approve'else'reject'end) or v.reason is distinct from e.original->>'reason'or v.created_at<>(e.original->>'reviewed_at')::timestamptz)then raise exception 'Existing submission review history differs';end if;
 if exists(select 1 from public.activity_evidence_upgrade_expected e join public.group_event_registrations r on e.kind='event'and e.id=r.id where(to_jsonb(r)-array['review_title','review_revision','review_evidence_id'])<>e.original or r.review_revision<>(case when e.original->>'review_body'is null then 0 else 1 end) or r.review_title is not null or r.review_evidence_id is not null)then raise exception 'Existing event review changed during backfill';end if;
 if(select count(*)from public.group_event_review_revisions where registration_id::text like'e9760000-%')<>1 or exists(select 1 from public.group_event_review_revisions v join public.activity_evidence_upgrade_expected e on e.kind='event'and e.id=v.registration_id where v.revision<>1 or v.body<>e.original->>'review_body'or v.created_at<>(e.original->>'reviewed_at')::timestamptz or v.evidence_id is not null)then raise exception 'Existing event review revision differs';end if;
 if not exists(select 1 from pg_trigger where tgrelid='public.group_mission_submission_revisions'::regclass and tgname='group_activity_history_immutable')or not exists(select 1 from pg_trigger where tgrelid='public.group_event_registrations'::regclass and tgname='group_release_deleted_activity_evidence')then raise exception 'Post-backfill triggers not installed';end if;
 if not exists(select 1 from pg_constraint where conrelid='public.group_mission_submission_revisions'::regclass and condeferrable and condeferred)then raise exception 'Runtime deferred FK semantics changed';end if;
 raise notice 'PASS existing submission/review backfill preserves originals, timestamps, statuses and deferred FK definitions';
end $$;
drop table public.activity_evidence_upgrade_expected;
